const company = $('Get Company Details').item.json;
const items = $input.all();
const pitches = items.map(it => it.json);
const baseUrl = 'https://cancheros.site';

const nowCo = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Bogota' }));
const yyyy = nowCo.getFullYear();
const mm = String(nowCo.getMonth() + 1).padStart(2, '0');
const dd = String(nowCo.getDate()).padStart(2, '0');
const todayDate = `${yyyy}-${mm}-${dd}`;

const tomorrowDateObj = new Date(nowCo.getTime() + 24 * 60 * 60 * 1000);
const tomorrowYyyy = tomorrowDateObj.getFullYear();
const tomorrowMm = String(tomorrowDateObj.getMonth() + 1).padStart(2, '0');
const tomorrowDd = String(tomorrowDateObj.getDate()).padStart(2, '0');
const tomorrowDate = `${tomorrowYyyy}-${tomorrowMm}-${tomorrowDd}`;

const currentHour = nowCo.getHours();
const currentMinutes = nowCo.getMinutes();
const currentTimeFormatted = nowCo.toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit', hour12: true });

const pitchesFormatted = pitches.map(p => ({
  id: p.id,
  name: p.name,
  type: p.type || 'Fútbol',
  surface: p.surface || 'Sintética',
  price: p.price_per_hour || 0,
  priceFormatted: `$${(p.price_per_hour || 0).toLocaleString('es-CO')}`,
  link: `${baseUrl}/cancha/${p.id}`
}));

const pitchLinksGuide = pitchesFormatted.map(p => 
  `• Cancha: "${p.name}" (${p.type}, ${p.surface}, ${p.priceFormatted}/hr) -> Link único: ${p.link}`
).join('\n');

return [{
  json: {
    companyId: company.id,
    companyName: company.name,
    todayDate,
    tomorrowDate,
    currentHour,
    currentMinutes,
    currentTimeFormatted,
    totalPitches: pitches.length,
    pitchLinksGuide,
    pitchesFormatted,
    baseUrl
  }
}];

