const pitchesCtx = $('Format Pitches Context').item.json;
const currentHour = pitchesCtx.currentHour;
const currentMinutes = pitchesCtx.currentMinutes;
const todayDate = pitchesCtx.todayDate;
const tomorrowDate = pitchesCtx.tomorrowDate;
const baseUrl = 'https://cancheros.site';

function formatSlots(pitchesData, isToday) {
  if (!Array.isArray(pitchesData) || pitchesData.length === 0) return 'Sin datos de disponibilidad.';

  let result = '';
  for (const pitch of pitchesData) {
    const available = (pitch.slots || []).filter(s => {
      if (s.status !== 'available') return false;
      if (isToday) {
        // Filtrar horas pasadas de hoy
        const [h] = s.time.split(':').map(Number);
        if (h < currentHour) return false;
        if (h === currentHour && currentMinutes > 30) return false;
      }
      return true;
    });

    if (available.length === 0) {
      result += `• ${pitch.pitch_name}: SIN DISPONIBILIDAD\n`;
    } else {
      const slots = available.slice(0, 6).map(s => {
        const price = (s.price || pitch.price_per_hour || 0).toLocaleString('es-CO');
        return `${s.time} ($${price}/hr)`;
      }).join(', ');
      const link = `${baseUrl}${pitch.profile_url || '/cancha/' + pitch.pitch_id}`;
      result += `• ${pitch.pitch_name}: ${slots}\n  Link: ${link}\n`;
    }
  }
  return result.trim();
}

let todayData = [];
let tomorrowData = [];

try {
  const todayRaw = $('Get Today Availability').item.json;
  todayData = Array.isArray(todayRaw) ? todayRaw : [];
} catch(e) { todayData = []; }

try {
  const tomorrowRaw = $('Get Tomorrow Availability').item.json;
  tomorrowData = Array.isArray(tomorrowRaw) ? tomorrowRaw : [];
} catch(e) { tomorrowData = []; }

const todayAvailText = formatSlots(todayData, true);
const tomorrowAvailText = formatSlots(tomorrowData, false);

return [{
  json: {
    ...pitchesCtx,
    todayAvailText,
    tomorrowAvailText,
    availabilityContext: `DISPONIBILIDAD HOY (${todayDate}):\n${todayAvailText}\n\nDISPONIBILIDAD MANANA (${tomorrowDate}):\n${tomorrowAvailText}`
  }
}];
